private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (bb.hasRemaining()) {
        int b = bb.get() & 0xFF;
        if (b < 0x80) {
            sb.append((char) b);
        } else if ((b & 0xE0) == 0xC0) {
            if (bb.remaining() < 1) {
                break;
            }
            int b2 = bb.get() & 0xFF;
            if ((b2 & 0xC0) != 0x80) {
                break;
            }
            sb.append((char) (((b & 0x1F) << 6) | (b2 & 0x3F)));
        } else if ((b & 0xF0) == 0xE0) {
            if (bb.remaining() < 2) {
                break;
            }
            int b2 = bb.get() & 0xFF;
            int b3 = bb.get() & 0xFF;
            if ((b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80) {
                break;
            }
            sb.append((char) (((b & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F)));
        } else if ((b & 0xF8) == 0xF0) {
            if (bb.remaining() < 3) {
                break;
            }
            int b2 = bb.get() & 0xFF;
            int b3 = bb.get() & 0xFF;
            int b4 = bb.get() & 0xFF;
            if ((b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80 || (b4 & 0xC0) != 0x80) {
                break;
            }
            sb.append((char) (((b & 0x07) << 18) | ((b2 & 0x3F) << 12) | ((b3 & 0x3F) << 6) | (b4 & 0x3F)));
        } else {
            break;
        }
    }
    return i + bb.position();
}
