public static int nextPrime(int desiredCapacity) {
    int capacity = desiredCapacity;
    if (capacity < 2) {
        return 2;
    }
    while (!isPrime(capacity)) {
        capacity++;
    }
    if (desiredCapacity >= 1000 && capacity - desiredCapacity > 0.11 * desiredCapacity) {
        capacity = findClosestPrime(desiredCapacity);
    }
    return capacity;
}

private static boolean isPrime(int number) {
    if (number <= 1) {
        return false;
    }
    for (int i = 2; i <= Math.sqrt(number); i++) {
        if (number % i == 0) {
            return false;
        }
    }
    return true;
}

private static int findClosestPrime(int number) {
    int lowerPrime = number;
    int upperPrime = number;
    while (!isPrime(lowerPrime)) {
        lowerPrime--;
    }
    while (!isPrime(upperPrime)) {
        upperPrime++;
    }
    return upperPrime - number < number - lowerPrime ? upperPrime : lowerPrime;
}
